/// Renders [raw] as a YAML scalar: booleans/numbers verbatim, plain-safe
/// strings unquoted, everything else JSON-quoted (a JSON string is a valid
/// YAML double-quoted scalar — the same convention the `prompts:` section
/// uses).
String renderYamlScalar(String raw) {
  if (raw == 'true' || raw == 'false' || raw == 'null' || raw == '~') {
    return raw;
  }
  if (int.tryParse(raw) != null) return raw;
  if (double.tryParse(raw) != null) return raw;
  final plainSafe = RegExp(r'^[A-Za-z0-9_.~][A-Za-z0-9_./@+-]*$');
  final uri = RegExp(r'^[a-z][a-z0-9+.-]*://\S*$');
  return plainSafe.hasMatch(raw) || uri.hasMatch(raw) ? raw : jsonEncode(raw);
}

/// Edits [text] so the dotted [segments] path carries [leafLines] (one
/// scalar line, or a multi-line yaml block), keeping every unrelated line
/// (including comments) byte-identical:
///
/// - an existing scalar line is rewritten in place, preserving a trailing
///   ` # comment`;
/// - an existing block (or scalar replaced by a block) is swapped for
///   [leafLines], leaving the rest of the parent block untouched;
/// - a missing key is inserted at the top of its parent's block;
/// - a missing top-level section is appended at the end of the file;
/// - descending into an inline scalar is a [ConfigException] (type clash).
///
/// Split into a per-segment scan helper to stay under the repo's CRAP
/// ratchet (crap4dart threshold 12).
String upsertYamlPath(
  String text,
  List<String> segments,
  List<String> leafLines,
) {
  final hadTrailingNewline = text.endsWith('\n');
  final lines = text.isEmpty
      ? <String>[]
      : (hadTrailingNewline ? text.substring(0, text.length - 1) : text).split(
          '\n',
        );
  var cursor = 0;
  for (var depth = 0; depth < segments.length; depth++) {
    final found = _findKeyLine(lines, segments, depth, cursor);
    if (found < 0) {
      return _insertChain(
        lines,
        segments,
        depth,
        cursor,
        leafLines,
        hadTrailingNewline,
      );
    }
    if (depth == segments.length - 1) {
      return _replaceLeaf(
        lines,
        segments[depth],
        depth,
        found,
        leafLines,
        hadTrailingNewline,
      );
    }
    final inline = _inlineValue(lines[found]);
    if (inline != null && inline.isNotEmpty) {
      throw ConfigException(
        '"${segments.sublist(0, depth + 1).join('.')}" is a scalar — '
        'cannot set a deeper key under it',
      );
    }
    cursor = found + 1;
  }
  // Unreachable: the leaf always returns inside the loop.
  throw StateError('upsertYamlPath fell through');
}

/// Edits [text] so the dotted [segments] path is REMOVED, keeping every
/// unrelated line byte-identical:
///
/// - the leaf key line and its block body are deleted;
/// - an ancestor whose block becomes empty is deleted too (a removed last
///   leaf under `models.overrides.zai.glm` drops the emptied `glm:` /
///   `zai:` blocks up the chain);
/// - a missing path is a no-op.
///
/// Same line-scan rules as [upsertYamlPath] (the CRAP ratchet split those
/// helpers out; this one shares them).
String removeYamlPath(String text, List<String> segments) {
  if (segments.isEmpty) return text;
  final hadTrailingNewline = text.endsWith('\n');
  final lines = text.isEmpty
      ? <String>[]
      : (hadTrailingNewline ? text.substring(0, text.length - 1) : text).split(
          '\n',
        );
  final foundAt = <int>[];
  var cursor = 0;
  for (var depth = 0; depth < segments.length; depth++) {
    final found = _findKeyLine(lines, segments, depth, cursor);
    if (found < 0) return text; // absent path — nothing to remove
    foundAt.add(found);
    cursor = found + 1;
  }
  // Delete deepest-first: the leaf's block body, then emptied ancestors.
  for (var depth = segments.length - 1; depth >= 0; depth--) {
    final keyLine = foundAt[depth];
    final end = _blockEnd(lines, keyLine, depth);
    lines.removeRange(keyLine, end);
    // An emptied ancestor block: the parent key line now carries no body.
    if (depth > 0) {
      final parentLine = foundAt[depth - 1];
      if (_blockEnd(lines, parentLine, depth - 1) == parentLine + 1) {
        continue; // loop's next iteration removes the emptied parent
      }
      break;
    }
  }
  return _join(lines, hadTrailingNewline);
}

/// The index of the line declaring `segments[depth]` at [cursor]'s block
/// level, or -1. The scan stops when the indentation backs out of the
/// parent block. A key matches in BOTH on-disk spellings — the bare form
/// and the `jsonEncode`-quoted form the typed emitters render
/// (`models.overrides` providers/model ids, `models.custom` names —
/// `ModelCapabilityOverrides.toYaml`); the two spell the SAME yaml key,
/// and missing the quoted one used to insert a duplicate bare chain
/// whose pre-write parse threw `YamlException: Duplicate mapping key`
/// (gh-1787).
int _findKeyLine(
  List<String> lines,
  List<String> segments,
  int depth,
  int cursor,
) {
  final indent = '  ' * depth;
  final tail = r':(\s.*)?$';
  final key = RegExp.escape(segments[depth]);
  final quoted = RegExp.escape(jsonEncode(segments[depth]));
  final pattern = RegExp('^${RegExp.escape(indent)}(?:$key|$quoted)$tail');
  for (var i = cursor; i < lines.length; i++) {
    if (_indentOf(lines[i]) < depth * 2 && i > cursor) break;
    if (pattern.hasMatch(lines[i])) return i;
  }
  return -1;
}

/// Whether a single [leafLines] entry may ride the `key: value` line.
/// A rendered block entry (a `- item` sequence line — dash SPACE, the
/// yaml sequence indicator — or a bare `-`) must go under a bare `key:`
/// line — gluing it inline produced invalid yaml for one-element
/// lists/maps. A negative number scalar (`-1`) is NOT an entry: the
/// plain `startsWith('-')` check corrupted every nested scalar upsert
/// with a negative value (issue #393 retry knobs).
bool _inlineSafeLine(String line) {
  final trimmed = line.trim();
  if (trimmed.startsWith('- ') || trimmed == '-') return false;
  // An indented line is a block map entry; flow-empties stay inline-safe.
  if (line != trimmed) return false;
  return true;
}

/// Inserts the missing `segments[depth..]` chain — at EOF for a new
/// top-level section, otherwise at the top of the parent's block — and
/// returns the joined text.
///
/// The inserted keys share the parent block's key spelling (gh-1787): a
/// block the typed emitters render with quoted keys (`"copilot":` —
/// `ModelCapabilityOverrides.toYaml`) grows a quoted key, never a bare
/// duplicate that the yaml parser reads as a SECOND mapping entry (the
/// duplicate threw `YamlException: Duplicate mapping key` at the pre-
/// write validation, and the write never landed).
String _insertChain(
  List<String> lines,
  List<String> segments,
  int depth,
  int cursor,
  List<String> leafLines,
  bool hadTrailingNewline,
) {
  final insertAt = depth == 0 ? lines.length : cursor;
  if (depth == 0 && lines.isNotEmpty && lines.last.trim().isNotEmpty) {
    lines.add('');
  }
  final quoted = depth > 0 && _childrenQuoted(lines, cursor - 1, depth);
  String spelling(String key) => quoted ? jsonEncode(key) : key;
  var at = insertAt;
  for (var d = depth; d < segments.length; d++) {
    final isLeaf = d == segments.length - 1;
    if (isLeaf && leafLines.length == 1 && _inlineSafeLine(leafLines[0])) {
      lines.insert(at, '${'  ' * d}${spelling(segments[d])}: ${leafLines[0]}');
      break;
    }
    lines.insert(at++, '${'  ' * d}${spelling(segments[d])}:');
    if (isLeaf) {
      for (final line in leafLines) {
        lines.insert(at++, line);
      }
    }
  }
  return _join(lines, hadTrailingNewline);
}

/// Whether the existing children of the block opened at [parentLine] spell
/// their keys quoted (`"key":` — the typed emitters' jsonEncode shape).
/// The first non-comment key line at [childDepth]'s exact indent decides;
/// grandchildren are skipped, a dedent ends the block. A parent with no
/// visible children (fresh section) stays bare — the legacy shape.
bool _childrenQuoted(List<String> lines, int parentLine, int childDepth) {
  final indent = '  ' * childDepth;
  for (var i = parentLine + 1; i < lines.length; i++) {
    final line = lines[i];
    if (line.trim().isEmpty || _indentOf(line) > childDepth * 2) continue;
    if (_indentOf(line) < childDepth * 2) return false;
    if (line.startsWith('$indent#')) continue;
    return line.startsWith('$indent"');
  }
  return false;
}

/// Swaps the leaf key line at [found] for [leafLines]: a single line keeps
/// the key's trailing comment inline, a block replaces the key's old body
/// (scalar or nested block) up to the parent's dedent.
String _replaceLeaf(
  List<String> lines,
  String key,
  int depth,
  int found,
  List<String> leafLines,
  bool hadTrailingNewline,
) {
  final indent = '  ' * depth;
  final comment = _trailingComment(lines[found]);
  // The found line's own spelling is preserved (gh-1787): a quoted key
  // line is rewritten quoted — the edit stays byte-stable within its
  // block's style instead of flipping the key to the bare form.
  final keyText = lines[found].startsWith('$indent"') ? jsonEncode(key) : key;
  if (leafLines.length == 1 && _inlineSafeLine(leafLines[0])) {
    lines[found] = '$indent$keyText: ${leafLines[0]}$comment';
    return _join(lines, hadTrailingNewline);
  }
  lines[found] = '$indent$keyText:$comment';
  final end = _blockEnd(lines, found, depth);
  lines.removeRange(found + 1, end);
  for (var i = 0; i < leafLines.length; i++) {
    lines.insert(found + 1 + i, leafLines[i]);
  }
  return _join(lines, hadTrailingNewline);
}

/// The index after the last line of the block body under the key line at
/// [keyLine] (indent [depth]); blank lines inside the block are consumed,
/// a blank line separating it from the next section is kept.
int _blockEnd(List<String> lines, int keyLine, int depth) {
  var end = keyLine + 1;
  while (end < lines.length) {
    final line = lines[end];
    if (_indentOf(line) > depth * 2) {
      end++;
      continue;
    }
    if (line.trim().isEmpty) {
      final next = end + 1 < lines.length ? lines[end + 1] : '';
      if (next.isEmpty || _indentOf(next) > depth * 2) {
        end++;
        continue;
      }
    }
    break;
  }
  return end;
}

/// The leaf value lines for a config value: a JSON array/object renders
/// as a yaml block under the key (list-valued keys — `customProviders`,
/// the `roles:` chains, `redact:` lists); anything else stays the single
/// scalar line `renderYamlScalar` always wrote. Shared by `config set`
/// and the settings flows' surgical upsert.
List<String> configLeafLines(String value, {required int depth}) {
  final raw = value.trim();
  if (!raw.startsWith('[') && !raw.startsWith('{')) {
    return [renderYamlScalar(value)];
  }
  final Object? decoded;
  try {
    decoded = jsonDecode(raw);
  } on FormatException {
    return [renderYamlScalar(value)];
  }
  if (decoded is! List && decoded is! Map) {
    return [renderYamlScalar(value)];
  }
  return _renderBlockLines(decoded, keyIndent: depth * 2);
}

